// Unbound portable layout candidate. No native calls and no default fixture/PID.
// Bind the exact sibling <engine>.scope.json SHA before compiling a delivery DLL.
using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
namespace McgsInternalBridge {
 internal static class NativeEngineeringDeliveryLayout {
  internal const string ExpectedConfigurationSha256="PENDING";
  internal const string ExpectedTransportClientSha256="6314e35b3420c544e149e4f0432e6db903b3ac493c14031b10c87ac37cf0669a";
  sealed class Layout {internal string File,Sha,Task,Engineering,Runtime,Install,Editor,Transport,TransportSha;}
  static readonly object sync=new object();static Layout loaded;
  static Layout Current{get{lock(sync){if(loaded==null)loaded=Load();return loaded;}}}
  internal static string ConfigurationSha256{get{return Current.Sha;}}
  internal static string TaskRoot{get{return Current.Task;}}
  internal static string EngineeringRoot{get{return Current.Engineering;}}
  internal static string EvidenceRoot{get{return Path.Combine(EngineeringRoot,"task-evidence");}}
  internal static string RuntimeRoot{get{return Current.Runtime;}}
  internal static string WorkingRoot{get{return Path.Combine(RuntimeRoot,"engineering");}}
  internal static string InstallRoot{get{return Current.Install;}}
  internal static string EditorExecutable{get{return Current.Editor;}}
  internal static string ProgramRoot{get{return Path.GetDirectoryName(EditorExecutable);}}
  internal static string TransportClientFile{get{return Current.Transport;}}
  internal static string TransportClientSha256{get{return Current.TransportSha;}}
  static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static byte[] ReadRegular(string file,int bound){NoReparse(file);Require(File.Exists(file)&&(File.GetAttributes(file)&(FileAttributes.Directory|FileAttributes.ReparsePoint))==0,"Delivery layout requires an existing regular file.");using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){Require(stream.Length>0&&stream.Length<=bound,"Delivery layout file exceeds its bound.");var bytes=new byte[(int)stream.Length];int at=0;while(at<bytes.Length){int n=stream.Read(bytes,at,bytes.Length-at);if(n==0)throw new EndOfStreamException();at+=n;}return bytes;}}
  static string Text(Dictionary<string,object> map,string key){object value;Require(map.TryGetValue(key,out value)&&value is string&&!String.IsNullOrEmpty((string)value)&&((string)value).IndexOf('\0')<0,"Delivery layout needs exact text: "+key);return(string)value;}
  static string Absolute(string text){Require(!String.IsNullOrEmpty(text)&&text.IndexOf('\0')<0&&Regex.IsMatch(text,@"\A(?:[A-Za-z]:[\\/]|\\\\[^\\/]+[\\/][^\\/]+(?:[\\/]|\z))"),"Delivery path must be explicit and fully absolute, including its drive or UNC share.");string full=Path.GetFullPath(text),root=Path.GetPathRoot(full);return full.Equals(root,StringComparison.OrdinalIgnoreCase)?root:full.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);}
  static bool Within(string path,string root){return path.Equals(root,StringComparison.OrdinalIgnoreCase)||path.StartsWith(root.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
  static void NoReparse(string path){for(string at=Path.GetFullPath(path);!String.IsNullOrEmpty(at);){if(File.Exists(at)||Directory.Exists(at))Require((File.GetAttributes(at)&FileAttributes.ReparsePoint)==0,"Delivery path ancestor is a reparse point.");string parent=Path.GetDirectoryName(at);if(parent==at)break;at=parent;}}
  static string DirectoryPath(string text){string full=Absolute(text);Require(Directory.Exists(full),"Delivery directory is absent.");NoReparse(full);return full;}
  static string EditorImage(string text,bool inspectPe){
   string file=Absolute(text);NoReparse(file);Require(File.Exists(file)&&(File.GetAttributes(file)&(FileAttributes.Directory|FileAttributes.ReparsePoint))==0,"Selected engineering executable is absent or not a regular file.");
   if(inspectPe)using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var reader=new BinaryReader(stream)){
    Require(stream.Length>=64&&reader.ReadUInt16()==0x5a4d,"Selected editor has no valid DOS/PE header.");stream.Position=60;uint pe=reader.ReadUInt32();Require(pe>=64&&(long)pe+24<=stream.Length,"Selected editor PE header is truncated.");
    stream.Position=pe;Require(reader.ReadUInt32()==0x00004550,"Selected editor PE signature differs.");ushort machine=reader.ReadUInt16(),sections=reader.ReadUInt16();stream.Position+=12;ushort optional=reader.ReadUInt16(),flags=reader.ReadUInt16();
    Require(machine==0x14c,"Selected editor must be I386/x86; x64/ARM cannot use this bootstrap.");Require(optional>=96&&(long)pe+24+optional<=stream.Length&&reader.ReadUInt16()==0x10b,"Selected editor must have a complete PE32 optional header.");Require((flags&2)!=0&&(flags&0x2000)==0,"Selected editor must be an executable, not a DLL.");
    long table=(long)pe+24+optional;Require(sections>=1&&sections<=96&&table+sections*40<=stream.Length,"Selected editor PE section table is truncated.");
    for(int i=0;i<sections;i++){stream.Position=table+i*40+16;uint size=reader.ReadUInt32(),offset=reader.ReadUInt32();Require(size==0||(offset!=0&&(long)offset+size<=stream.Length),"Selected editor section data exceeds the image.");}
   }return file;
  }
  static Layout Load(){Require(Regex.IsMatch(ExpectedConfigurationSha256,@"\A[a-f0-9]{64}\z"),"Delivery configuration is unbound; no host/project action is allowed.");string assembly=typeof(NativeEngineeringDeliveryLayout).Assembly.Location;Require(!String.IsNullOrEmpty(assembly),"Delivery engine has no verified local assembly location.");string file=Path.ChangeExtension(Path.GetFullPath(assembly),".scope.json");byte[] bytes=ReadRegular(file,65536);Require(Hash(bytes)==ExpectedConfigurationSha256,"Delivery sibling configuration SHA differs.");string text=new UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');var map=new JavaScriptSerializer{MaxJsonLength=65536}.Deserialize<Dictionary<string,object>>(text);Require(map!=null&&map.Count==(map.ContainsKey("editor_executable")?8:7)&&map.ContainsKey("schema")&&map["schema"] is int&&(int)map["schema"]==1,"Delivery scope schema differs.");foreach(string key in map.Keys)Require(Array.IndexOf(new[]{"schema","task_root","engineering_root","runtime_root","install_root","transport_client_file","transport_client_sha256","editor_executable"},key)>=0,"Unknown delivery configuration key.");var result=new Layout{File=file,Sha=Hash(bytes),Task=DirectoryPath(Text(map,"task_root")),Engineering=DirectoryPath(Text(map,"engineering_root")),Runtime=DirectoryPath(Text(map,"runtime_root")),Install=DirectoryPath(Text(map,"install_root")),Transport=Absolute(Text(map,"transport_client_file")),TransportSha=Text(map,"transport_client_sha256")};Require(!result.Task.TrimEnd('\\','/').Equals(Path.GetPathRoot(result.Task).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase),"The owned task root cannot be a whole volume.");Require(Within(result.Runtime,result.Task)&&!result.Runtime.Equals(result.Task,StringComparison.OrdinalIgnoreCase),"Runtime must be an explicit child of the owned task root.");Require(!result.Engineering.Equals(result.Runtime,StringComparison.OrdinalIgnoreCase)&&!Within(result.Engineering,result.Runtime)&&!Within(result.Runtime,result.Engineering),"Frozen engineering payload and writable runtime must be disjoint.");Require(Within(result.Transport,result.Task)||Within(result.Transport,result.Engineering),"Transport source is outside both declared owned/artifact roots.");Require(result.TransportSha==ExpectedTransportClientSha256&&Hash(ReadRegular(result.Transport,1024*1024))==result.TransportSha,"At-most-once transport source SHA differs.");result.Editor=EditorImage(map.ContainsKey("editor_executable")?Text(map,"editor_executable"):Path.Combine(result.Install,"Program","McgsSetPro.exe"),map.ContainsKey("editor_executable"));Require(Within(result.Editor,result.Install),"Selected editor escapes the declared installation root.");return result;}
  internal static void Check(){Layout value=Current;Require(Hash(ReadRegular(value.File,65536))==value.Sha,"Bound delivery configuration changed after load.");NoReparse(value.Task);NoReparse(value.Engineering);DirectoryPath(EvidenceRoot);NoReparse(value.Runtime);NoReparse(value.Install);Require(Hash(ReadRegular(value.Transport,1024*1024))==value.TransportSha,"Bound transport source changed.");}
 }
}
